import {mountViaReader89} from './vias-reader89.js?v=104';
const base='documentacion/estudio89/';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const normalize89=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function searchPages89(docs,query,source=''){const words=normalize89(query).trim().split(/\s+/).filter(Boolean);return docs.filter(d=>!source||d.id===source).flatMap(d=>d.content.filter(p=>words.every(w=>normalize89(p.text).includes(w))).map(p=>({...p,source:d.id,name:d.name,file:d.file})));}
export function energyState89({era='modern',traction=true,auxiliary=true,fault=false}={}){return {input:era==='historic'?85:230,distribution:15,traction:traction&&!fault?750:0,auxiliary,canTraction:traction&&!fault};}
let dataPromise,pending;
export function setStudyRequest89(r){pending=r;}
async function getData(){if(!dataPromise)dataPromise=(async()=>{const get=async p=>{const compact=p==='prescripciones2020.json',r=await fetch(base+p+(compact?'.gz':'')+'?v=97');if(!r.ok)throw Error('Documento no disponible: '+p);return compact?new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).json():r.json();};const [catalog,criteria]=await Promise.all([get('catalogo.json'),get('criterios.json')]);const docs=await Promise.all(catalog.map(d=>get(d.id+'.json')));return {docs,criteria};})().catch(e=>{dataPromise=null;throw e;});return dataPromise;}
export async function mountKnowledge89(host){
 const node=document.createElement('section');node.className='knowledge89';node.innerHTML='<p role="status">Recuperando documentación técnica…</p>';host.prepend(node);
 try{
 const {docs,criteria}=await getData();if(!node.isConnected)return;
 node.innerHTML=`<header><span>ARCHIVO TÉCNICO · REVISIÓN 89</span><h2>Entender el tren, pieza por pieza</h2><p>${docs.length} documentos · ${docs.reduce((n,d)=>n+d.pages,0)} páginas y diapositivas consultables. Referencias históricas identificadas; valores sin confirmar separados de la simulación.</p></header><nav aria-label="Consulta técnica">${[['reader','Documentos'],['energy','Energía'],['conflicts','Discrepancias'],['coverage','Qué está integrado'],['sources','Fuentes oficiales']].map(([id,label])=>`<button data-tab="${id}" aria-pressed="false">${label}</button>`).join('')}</nav><div data-panel="reader"><div class="k89-filters"><label>Documento<select id="k89-source"><option value="">Todos</option>${docs.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></label><label>Buscar palabras<input id="k89-query" type="search" placeholder="batería, puertas, rectificador…"></label></div><p id="k89-count" role="status"></p><div class="k89-reader"><div id="k89-results" aria-label="Páginas encontradas"></div><article><h3 id="k89-title"></h3><p id="k89-method"></p><div class="k89-actions"><button id="k89-prev">Anterior</button><button id="k89-next">Siguiente</button><a id="k89-original" target="_blank" rel="noopener">Ver documento</a></div><pre id="k89-text"></pre></article></div><details><summary>Archivos y procedencia</summary>${docs.map(d=>`<p><a href="${base+d.file}" target="_blank" rel="noopener">${esc(d.name)}</a> · ${d.pages} unidades · ${esc(d.copy)}</p>`).join('')}<p>Los manuales escaneados se ofrecen como copias de consulta. Los originales se preservan en el código fuente. El OCR puede confundir cifras, acentos y símbolos; abre la página para contrastarlos. La numeración del lector corresponde al archivo, no al folio impreso.</p><a href="${base}catalogo.json" download>Descargar procedencia y huellas SHA-256</a></details></div><div data-panel="energy" hidden><h3>¿Cómo llega la energía al tren?</h3><p>Modelo conceptual independiente: estos mandos no accionan el tren del simulador. La modernización de Metro-Energía corresponde a L1–L3; no se atribuye este esquema a toda la Línea 8.</p><label>Referencia de recepción <select id="k89-era"><option value="modern">Metro-Energía · referencia de 2023</option><option value="historic">Manual histórico · 85 kV</option></select></label><div class="k89-chain"><article><small>Recepción</small><strong id="k89-input"></strong></article><article><small>Distribución</small><strong>15 kV CA</strong></article><article><small>Rectificación · tracción</small><strong id="k89-traction"></strong></article></div><div class="k89-actions"><label><input id="k89-power" type="checkbox" checked> Alimentación de tracción</label><label><input id="k89-aux" type="checkbox" checked> Servicios auxiliares</label><label><input id="k89-fault" type="checkbox"> Falla virtual en tracción</label></div><p id="k89-energy-state" role="status"></p><p>Los servicios auxiliares tienen una rama propia. El banco didáctico de mantenimiento usa 24 V CC simulados; no representa los 750 V de tracción ni la batería del tren.</p><button data-source="energia2" data-page="23">Consultar rectificación</button></div><div data-panel="conflicts" hidden><h3>Datos que no deben mezclarse</h3>${criteria.conflicts.map(c=>`<article class="k89-card"><h4>${esc(c.title)}</h4><p>${esc(c.detail)}</p><strong>Aplicación: </strong>${esc(c.decision)}${c.source?`<p><button data-source="${c.source}" data-page="${c.page}">Consultar referencia · página ${c.page}</button></p>`:''}</article>`).join('')}</div><div data-panel="coverage" hidden><h3>Estado real de la integración</h3><p>Documento disponible, dato aplicado y modelo 3D terminado son estados diferentes. Esta revisión no acredita que todos los detalles del historial estén reproducidos.</p><div class="k89-table"><table><thead><tr><th>Área</th><th>Estado</th><th>Alcance y pendiente</th></tr></thead><tbody>${criteria.coverage.map(c=>`<tr><td>${esc(c.area)}</td><td>${esc(c.status)}</td><td>${esc(c.detail)}</td></tr>`).join('')}</tbody></table></div><a href="${base}criterios.json" download>Descargar revisión y pendientes</a></div><div data-panel="sources" hidden><h3>Contraste con fuentes públicas</h3><p>Consulta: 14 de octubre de 2026. Se distingue la fecha del documento de su aplicación al modelo.</p>${criteria.web.map(w=>`<article class="k89-card"><h4><a href="${esc(w.url)}" target="_blank" rel="noopener">${esc(w.title)}</a></h4><p>${esc(w.detail)}</p></article>`).join('')}</div>`;
 const $=id=>node.querySelector('#'+id);let results=[],selected=0;
 function tab(id){node.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==id);node.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===id)));}
 function select(index){selected=index;const p=results[index];$('k89-title').textContent=p?`${p.name} · ${p.page}`:'Sin coincidencias';$('k89-text').textContent=p?.text||'Prueba otras palabras o selecciona otro documento.';$('k89-method').textContent=p?.method||'';$('k89-original').hidden=!p;if(p)$('k89-original').href=base+p.file+(/\.pdf$/.test(p.file)?'#page='+p.page:'');$('k89-prev').disabled=index<=0;$('k89-next').disabled=index>=results.length-1;node.querySelectorAll('[data-result]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.result)===index)));}
 function search(){results=searchPages89(docs,$('k89-query').value,$('k89-source').value);$('k89-count').textContent=results.length+' páginas o diapositivas';$('k89-results').innerHTML=results.map((p,i)=>`<button data-result="${i}"><b>${esc(p.source)} · ${p.page}</b><small>${esc(p.text.slice(0,85).replace(/\s+/g,' '))}</small></button>`).join('');select(0);}
 function open(source,page){tab('reader');$('k89-source').value=source;$('k89-query').value='';search();select(Math.max(0,results.findIndex(p=>p.page===Number(page))));node.scrollIntoView({block:'start'});}
 function energy(){const s=energyState89({era:$('k89-era').value,traction:$('k89-power').checked,auxiliary:$('k89-aux').checked,fault:$('k89-fault').checked});$('k89-input').textContent=s.input+' kV CA';$('k89-traction').textContent=s.traction?s.traction+' V CC':'Sin alimentación';$('k89-energy-state').textContent=`Tracción: ${s.canTraction?'disponible':'interrumpida'}. Servicios auxiliares: ${s.auxiliary?'alimentados':'desconectados'}.`;}
 node.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab)tab(b.dataset.tab);if(b.dataset.result!==undefined)select(Number(b.dataset.result));if(b.dataset.source)open(b.dataset.source,b.dataset.page);};
 $('k89-query').oninput=search;$('k89-source').onchange=search;$('k89-prev').onclick=()=>select(Math.max(0,selected-1));$('k89-next').onclick=()=>select(Math.min(results.length-1,selected+1));for(const id of ['era','power','aux','fault'])$('k89-'+id).onchange=energy;
 mountViaReader89(node.querySelector('[data-panel=coverage]'));tab('reader');search();energy();if(pending){open(pending.source,pending.page);pending=null;}
 }catch(e){node.textContent='No se pudo cargar el archivo técnico. Cierra y vuelve a abrir Documentación para reintentar.';console.error(e);}
}
